def execute(arguments):
    """
    进程管理

    参数:
        arguments (dict): 包含以下字段
            - operation (str): 操作类型
                - "list": 列出所有进程
                - "find": 查找进程
                - "kill": 终止进程
                - "info": 获取进程详情
            - name (str): 进程名称，find操作时使用
            - pid (int): 进程ID，kill/info操作时使用
            - force (bool): 强制终止，kill操作时使用，默认 False

    返回:
        dict: 包含操作结果的字典
            - success (bool): 是否成功
            - processes (list): 进程列表（list/find操作）
            - process (dict): 进程详情（info操作）
            - killed (bool): 是否已终止（kill操作）
            - error (str): 错误信息（失败时）
    """
    import os
    import platform

    operation = arguments.get("operation", "list")
    name = arguments.get("name", "")
    pid = arguments.get("pid")
    force = arguments.get("force", False)

    try:
        if operation == "list":
            try:
                import psutil
                processes = []
                for proc in psutil.process_iter(['pid', 'name', 'cpu_percent', 'memory_percent']):
                    try:
                        processes.append({
                            "pid": proc.info['pid'],
                            "name": proc.info['name'],
                            "cpu_percent": proc.info['cpu_percent'],
                            "memory_percent": round(proc.info['memory_percent'], 2)
                        })
                    except (psutil.NoSuchProcess, psutil.AccessDenied):
                        pass
                processes.sort(key=lambda x: x['cpu_percent'] or 0, reverse=True)
                return {"success": True, "processes": processes[:50], "count": len(processes)}
            except ImportError:
                is_windows = platform.system() == "Windows"
                if is_windows:
                    import subprocess
                    result = subprocess.run(["tasklist"], capture_output=True, text=True)
                    lines = result.stdout.strip().split("\n")[3:]
                    processes = []
                    for line in lines:
                        parts = line.split()
                        if len(parts) >= 2:
                            processes.append({"name": parts[0], "pid": int(parts[1])})
                    return {"success": True, "processes": processes, "count": len(processes)}
                else:
                    import subprocess
                    result = subprocess.run(["ps", "aux"], capture_output=True, text=True)
                    lines = result.stdout.strip().split("\n")[1:]
                    processes = []
                    for line in lines:
                        parts = line.split()
                        if len(parts) >= 11:
                            processes.append({"user": parts[0], "pid": int(parts[1]), "name": parts[10]})
                    return {"success": True, "processes": processes, "count": len(processes)}

        elif operation == "find":
            if not name:
                return {"success": False, "error": "请提供进程名称"}

            try:
                import psutil
                matches = []
                for proc in psutil.process_iter(['pid', 'name']):
                    try:
                        if name.lower() in proc.info['name'].lower():
                            matches.append({"pid": proc.info['pid'], "name": proc.info['name']})
                    except (psutil.NoSuchProcess, psutil.AccessDenied):
                        pass
                return {"success": True, "processes": matches, "count": len(matches)}
            except ImportError:
                return {"success": False, "error": "需要安装 psutil 库"}

        elif operation == "kill":
            if not pid:
                return {"success": False, "error": "请提供进程ID"}

            try:
                import psutil
                proc = psutil.Process(pid)
                if force:
                    proc.kill()
                else:
                    proc.terminate()
                return {"success": True, "killed": True, "pid": pid, "name": proc.name()}
            except ImportError:
                import signal
                os.kill(pid, signal.SIGKILL if force else signal.SIGTERM)
                return {"success": True, "killed": True, "pid": pid}

        elif operation == "info":
            if not pid:
                return {"success": False, "error": "请提供进程ID"}

            try:
                import psutil
                proc = psutil.Process(pid)
                info = {
                    "pid": proc.pid,
                    "name": proc.name(),
                    "status": proc.status(),
                    "create_time": proc.create_time(),
                    "cpu_percent": proc.cpu_percent(),
                    "memory_percent": proc.memory_percent(),
                    "num_threads": proc.num_threads(),
                    "exe": proc.exe(),
                    "cwd": proc.cwd(),
                    "cmdline": proc.cmdline()
                }
                return {"success": True, "process": info}
            except ImportError:
                return {"success": False, "error": "需要安装 psutil 库"}

        else:
            return {"success": False, "error": f"未知的操作: {operation}"}
    except Exception as e:
        return {"success": False, "error": f"操作失败: {str(e)}"}
